INSERT INTO "battle" ("id", "slug", "author_id", "title", "context", "category_id", "tags", "deadline", "created_at") VALUES
  ('seed_vb_1', 'vFkAvCoY', (SELECT id FROM "user" WHERE handle = 'brunchclub_19'), 'My husband turns on subtitles for EVERYTHING. Even stuff in English. Who''s right?', 'We''ve had this fight like 6 times this month. I can''t focus on the actual show.', 'other', '{}'::jsonb, now() + interval '80 hours', now() - interval '1172 minutes'),
  ('seed_vb_2', 'vhZftRAc', (SELECT id FROM "user" WHERE handle = 'cupcake_59'), 'He says if I make dinner, packing his lunch for tomorrow is ''basically the same thing''. Is it?', 'He''s a grown man with two working hands lol', 'other', '{}'::jsonb, now() + interval '87 hours', now() - interval '252 minutes'),
  ('seed_vb_3', 'vXsVKD88', (SELECT id FROM "user" WHERE handle = 'slowmornings_amir'), 'I spent $400 on Taylor tickets without asking first. My fiancé is LIVID. Who''s right?', 'We never set a rule. It''s from my own paycheck.', 'other', '{}'::jsonb, now() + interval '70 hours', now() - interval '2213 minutes'),
  ('seed_vb_4', 'vaEhUCUw', (SELECT id FROM "user" WHERE handle = 'cutesy_lily'), 'I told my mom we''re pregnant before 12 weeks. He''s furious. Who''s right?', 'She cried, it was beautiful. He says I broke our deal.', 'other', '{}'::jsonb, now() + interval '95 hours', now() - interval '2403 minutes'),
  ('seed_vb_5', 'vTZPFftD', (SELECT id FROM "user" WHERE handle = 'chicago_52'), 'She went through my phone while I was asleep. Found nothing. Now I''m the one who''s upset. Who''s right?', 'She says I''d been ''acting weird''. I was planning her birthday.', 'other', '{}'::jsonb, now() + interval '96 hours', now() - interval '1400 minutes'),
  ('seed_vb_6', 'vxSpbdFj', (SELECT id FROM "user" WHERE handle = 'doglover_91'), 'Party invite says 7pm. My wife wants to leave the house at 6:45. I say show up 7:30.', 'This happens before every single party.', 'other', '{}'::jsonb, now() + interval '91 hours', now() - interval '1842 minutes'),
  ('seed_vb_7', 'vGhteMvN', (SELECT id FROM "user" WHERE handle = 'doglover_71'), 'I cooked a full dinner. He thinks whoever''s ''less tired'' does the dishes. I think the cook never cleans.', 'Every night. Every single night.', 'other', '{}'::jsonb, now() + interval '88 hours', now() - interval '606 minutes'),
  ('seed_vb_8', 'viD8sDQc', (SELECT id FROM "user" WHERE handle = 'texas_46'), 'My bf keeps the thermostat at 74 and I''m sweating in my own apartment. I want 68. Who wins?', 'We share one thermostat and zero patience.', 'other', '{}'::jsonb, now() + interval '89 hours', now() - interval '1538 minutes'),
  ('seed_vb_9', 'vRa8HSZt', (SELECT id FROM "user" WHERE handle = 'roadtrip_jess'), 'He sat in the car scrolling for 20 min after getting home instead of coming inside to help with the kids', 'He says it''s his ''decompression time''. I''ve had both kids since 7am.', 'other', '{}'::jsonb, now() + interval '74 hours', now() - interval '2058 minutes'),
  ('seed_vb_10', 'vTpJP65H', (SELECT id FROM "user" WHERE handle = 'plantmom_steph'), 'My wife wants to split the honeymoon 50/50 even though I make 3x what she makes', 'Plot twist, I''m the one who wants to pay more. She refuses.', 'other', '{}'::jsonb, now() + interval '108 hours', now() - interval '63 minutes'),
  ('seed_vb_11', 'vUpFnTfw', (SELECT id FROM "user" WHERE handle = 'taconight_vee'), 'I took ONE sip of his iced mocha while pregnant and he made it a whole thing', 'He read that caffeine is bad and now he''s the caffeine police.', 'other', '{}'::jsonb, now() + interval '77 hours', now() - interval '1878 minutes'),
  ('seed_vb_12', 'vxEfrtuu', (SELECT id FROM "user" WHERE handle = 'doglover_91'), 'My boyfriend wants his gaming setup in OUR bedroom. RGB lights all night. I want it out.', 'Small apartment, no spare room. The RGB lights stay on all night.', 'other', '{}'::jsonb, now() + interval '95 hours', now() - interval '396 minutes'),
  ('seed_vb_13', 'vG3oUrPM', (SELECT id FROM "user" WHERE handle = 'chaotic_lexi40'), 'My husband told his whole friend group about our fertility struggles without asking me', 'He says he needed support too. I found out from his friend''s wife.', 'other', '{}'::jsonb, now() + interval '102 hours', now() - interval '1411 minutes'),
  ('seed_vb_14', 'vNHYAwro', (SELECT id FROM "user" WHERE handle = 'plantmom_nick'), 'I want separate blankets in bed (the Scandinavian way). He thinks it means we''re drifting apart.', 'I''m freezing, he steals everything, I sleep so much better alone under mine.', 'other', '{}'::jsonb, now() + interval '89 hours', now() - interval '2110 minutes'),
  ('seed_vb_15', 'vjam3raH', (SELECT id FROM "user" WHERE handle = 'goldenhour_dani62'), 'He goes to the gym 6am every day and leaves me with the morning chaos. Who''s right?', 'We have a 2 and 4 year old. Morning is the hardest part of the day.', 'other', '{}'::jsonb, now() + interval '88 hours', now() - interval '2497 minutes'),
  ('seed_vb_16', 'vdh8unjw', (SELECT id FROM "user" WHERE handle = 'engaged_tay14'), 'My girlfriend says I should''ve defended her when my mom made a comment about her weight. I froze. Who''s right?', 'Mom said ''are you sure you want seconds?'' at Thanksgiving.', 'other', '{}'::jsonb, now() + interval '98 hours', now() - interval '834 minutes'),
  ('seed_vb_17', 'vABdNrq2', (SELECT id FROM "user" WHERE handle = 'pinotnoir_mia77'), 'My husband invited his brother to stay with us for ''a couple weeks''. It''s been 3 months.', 'He doesn''t pay rent and eats all the snacks. Husband says family is family.', 'other', '{}'::jsonb, now() + interval '94 hours', now() - interval '1677 minutes'),
  ('seed_vb_18', 'vMwdiqE3', (SELECT id FROM "user" WHERE handle = 'newlywed_72'), 'Who''s right: he wants to name our son after himself (a Jr.). I hate the idea.', 'His dad is a Sr. too. It''s a ''tradition''.', 'other', '{}'::jsonb, now() + interval '90 hours', now() - interval '1700 minutes'),
  ('seed_vb_19', 'vdx4VVXX', (SELECT id FROM "user" WHERE handle = 'honeybee_max'), 'I left the dishwasher running while we were out. He says that''s a fire hazard and dangerous.', 'I''ve done this my whole life. He''s never once seen a fire.', 'other', '{}'::jsonb, now() + interval '115 hours', now() - interval '1737 minutes'),
  ('seed_vb_20', 'vCoofdfZ', (SELECT id FROM "user" WHERE handle = 'nurse_steph73'), 'She wants to spend every holiday at her parents'' because ''my family is more fun''', 'My mom cried last Christmas. It''s been 3 years in a row at hers.', 'other', '{}'::jsonb, now() + interval '100 hours', now() - interval '1499 minutes'),
  ('seed_vb_21', 'v4vd3iu4', (SELECT id FROM "user" WHERE handle = 'sundayreset_zoe'), 'My husband says I can''t go on my best friend''s 30th in Vegas. Every other place is fine. Who''s right?', 'Long weekend, 4 girls, all married. He says ''Vegas is different''.', 'other', '{}'::jsonb, now() + interval '90 hours', now() - interval '1915 minutes'),
  ('seed_vb_22', 'vLrXPgzb', (SELECT id FROM "user" WHERE handle = 'auntie_lily27'), 'He wants to use our wedding gift money on a new truck. I want it in savings.', 'We got $14k in gifts. His truck works fine.', 'other', '{}'::jsonb, now() + interval '76 hours', now() - interval '2380 minutes'),
  ('seed_vb_23', 'vcXhZsmn', (SELECT id FROM "user" WHERE handle = 'nurse_steph73'), 'My boyfriend says it''s fine to fall asleep on FaceTime with his female best friend. Is it?', 'They''ve been friends since they were 6. He says it''s just ''background noise''.', 'other', '{}'::jsonb, now() + interval '81 hours', now() - interval '889 minutes'),
  ('seed_vb_24', 'vTi4wTxD', (SELECT id FROM "user" WHERE handle = 'yogi_liv77'), 'I want to keep my last name when we get married. He says it means I''m not fully committed.', 'My name is on my business. I''ve built it for 9 years.', 'other', '{}'::jsonb, now() + interval '83 hours', now() - interval '100 minutes'),
